package main

import (
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/exec"
	"strings"
)

type User struct {
	ID       int    `json:"id"`
	Username string `json:"username"`
	Email    string `json:"email"`
	Role     string `json:"role"`
	IsAdmin  bool   `json:"is_admin"`
	APIKey   string `json:"api_key"`
}

var users = map[int]*User{
	1: {ID: 1, Username: "alice", Email: "alice@corp.io", Role: "viewer", IsAdmin: false, APIKey: "ak_readonly_001"},
	2: {ID: 2, Username: "bob", Email: "bob@corp.io", Role: "editor", IsAdmin: false, APIKey: "ak_editor_002"},
}

func updateProfile(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPut {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	// Authenticate user (simplified - normally from JWT)
	userID := 1 // hardcoded for demo

	user, exists := users[userID]
	if !exists {
		http.Error(w, "User not found", http.StatusNotFound)
		return
	}

	// VULNERABILITY: Directly unmarshal request body into user struct
	// This allows mass assignment of Role, IsAdmin, APIKey fields
	decoder := json.NewDecoder(r.Body)
	if err := decoder.Decode(user); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	// Post-update action: if admin, allow network diagnostics
	if user.IsAdmin {
		go runDiagnostics(user.Username)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(user)
}

func runDiagnostics(username string) {
	// Uses raw sockets for ICMP ping - requires CAP_NET_RAW
	cmd := exec.Command("ping", "-c", "1", "healthcheck.internal")
	output, err := cmd.CombinedOutput()
	if err != nil {
		log.Printf("[diag] ping failed for %s: %v", username, err)
		return
	}
	log.Printf("[diag] result for %s: %s", username, strings.TrimSpace(string(output)))
}

func adminPanel(w http.ResponseWriter, r *http.Request) {
	userID := 1
	user := users[userID]

	if !user.IsAdmin {
		http.Error(w, "Forbidden", http.StatusForbidden)
		return
	}

	// Admin can execute system commands for monitoring
	action := r.URL.Query().Get("action")
	if action == "netstat" {
		// Requires CAP_SYS_ADMIN for full namespace visibility
		cmd := exec.Command("nsenter", "--net=/proc/1/ns/net", "netstat", "-tlnp")
		output, err := cmd.CombinedOutput()
		if err != nil {
			fmt.Fprintf(w, "Error: %v\n", err)
			return
		}
		w.Write(output)
	} else if action == "ps" {
		cmd := exec.Command("ps", "aux")
		output, _ := cmd.CombinedOutput()
		w.Write(output)
	} else {
		fmt.Fprintf(w, "Available actions: netstat, ps\nHostname: %s\n", mustHostname())
	}
}

func mustHostname() string {
	h, _ := os.Hostname()
	return h
}

func main() {
	http.HandleFunc("/api/profile", updateProfile)
	http.HandleFunc("/api/admin", adminPanel)

	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
